/* OFF candidate: fixed metadata accessor for the additive CIMD receipts only.
   This creates no user/login/membership and changes no historical role or receipt.
   Permission provisioning requires separate destination review; never run in production
   merely because this file is present. Existing Case attestation retains its own identity. */
SET NOCOUNT ON; SET XACT_ABORT ON; SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON;
IF @@TRANCOUNT<>0 OR USER_NAME()<>'dbo' OR SESSION_CONTEXT(N'ShaleClientId') IS NOT NULL
 OR SESSION_CONTEXT(N'PrincipalUserId') IS NOT NULL
 THROW 59520,'Fresh unscoped owner installation required.',1;
BEGIN TRY
 BEGIN TRANSACTION;
 DECLARE @lock int;
 EXEC @lock=sys.sp_getapplock @Resource=N'AiSchemaV1',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=3000;
 IF @lock<0 OR NOT EXISTS(SELECT 1 FROM dbo.AiProductCapability WHERE Id=1 AND Enabled=0)
  OR NOT EXISTS(SELECT 1 FROM dbo.AiCimdProofControlV1 WHERE Id=1 AND Enabled=0)
  OR NOT EXISTS(SELECT 1 FROM dbo.AiCimdOAuthControlV1 WHERE Id=1 AND Enabled=0)
  THROW 59520,'Schema lock and all capabilities OFF required.',1;
 IF DATABASE_PRINCIPAL_ID(N'AiCimdAuthorizationCatalogV1') IS NOT NULL
  THROW 59520,'Reviewer role already exists; no automatic repair.',1;
 CREATE ROLE AiCimdAuthorizationCatalogV1 AUTHORIZATION dbo;
 GRANT VIEW DEFINITION TO AiCimdAuthorizationCatalogV1;
 GRANT SELECT ON OBJECT::sys.sql_expression_dependencies TO AiCimdAuthorizationCatalogV1;
 /* GENERATED_RECEIPT_ACCESSOR */
 DECLARE @accessor nvarchar(max)=CONVERT(nvarchar(max),);
 EXEC sys.sp_executesql @accessor;
 /* END_GENERATED_RECEIPT_ACCESSOR */
 GRANT EXECUTE ON OBJECT::dbo.AiCimdReadAuthorizationReceiptsV1 TO AiCimdAuthorizationCatalogV1;
 /* PR_A_REVIEWER_FINAL_CHECK */
 IF (SELECT COUNT(*) FROM sys.database_permissions WHERE grantee_principal_id=DATABASE_PRINCIPAL_ID(N'AiCimdAuthorizationCatalogV1'))<>3
  OR EXISTS(SELECT 1 FROM sys.database_permissions WHERE grantee_principal_id=DATABASE_PRINCIPAL_ID(N'AiCimdAuthorizationCatalogV1')
   AND NOT(state='G' AND grantor_principal_id=1 AND
    (class=0 AND permission_name='VIEW DEFINITION' OR class=1 AND minor_id=0 AND
     (permission_name='SELECT' AND major_id=OBJECT_ID(N'sys.sql_expression_dependencies')
      OR permission_name='EXECUTE' AND major_id=OBJECT_ID(N'dbo.AiCimdReadAuthorizationReceiptsV1')))))
  THROW 59520,'Metadata reviewer permission drift; installation rolled back.',1;
 COMMIT TRANSACTION;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK TRANSACTION; THROW; END CATCH;
